import{_ as i,c as a,o as t,ag as o}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"React tech-check","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"node-js/tech-check/react-tech-check.md","filePath":"node-js/tech-check/react-tech-check.md"}'),n={name:"node-js/tech-check/react-tech-check.md"};function l(r,e,s,p,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="react-tech-check" tabindex="-1">React tech-check <a class="header-anchor" href="#react-tech-check" aria-label="Permalink to “React tech-check”">​</a></h1><h2 id="coding-task-recursive-navigation-menu" tabindex="-1">Coding task: recursive navigation menu <a class="header-anchor" href="#coding-task-recursive-navigation-menu" aria-label="Permalink to “Coding task: recursive navigation menu”">​</a></h2><h2 id="build-a-navigation-component-from-an-array-of-menu-items" tabindex="-1">Build a navigation component from an array of menu items: <a class="header-anchor" href="#build-a-navigation-component-from-an-array-of-menu-items" aria-label="Permalink to “Build a navigation component from an array of menu items:”">​</a></h2><ul><li><p>Each item has an id, a label, and optional nestedItems.</p></li><li><p>Support arbitrary nesting depth.</p></li><li><p>Allow submenus to expand and collapse.</p></li><li><p>Keep submenus hidden initially.</p></li><li><p>Receive the data through props; fetching and styling are unnecessary.</p></li><li><p>Optional extension: How would you support additional item properties, such as onClick or a link?</p></li><li><p>Where should the key prop go when mapping items to components?</p></li><li><p>Do nested mapped items also need keys?</p></li><li><p>Will each recursively rendered navigation item have its own independent state?</p></li></ul><h2 id="jsx-and-component-return-values" tabindex="-1">JSX and component return values <a class="header-anchor" href="#jsx-and-component-return-values" aria-label="Permalink to “JSX and component return values”">​</a></h2><ul><li><p>What JavaScript can you write inside JSX curly braces? What restrictions apply?</p></li><li><p>Snippet question: Can you put the demonstrated statements directly inside JSX? If not, how could you restructure them?</p></li><li><p>What can a function component return?</p></li><li><p>Snippet comparison: What is the difference between rendering a component with JSX and invoking it as a function?</p><p><em>The exact expressions are unavailable. The discussion later connects this question to render props, so its intended scope is somewhat ambiguous.</em></p></li></ul><h2 id="state-initialization-and-batching" tabindex="-1">State, initialization, and batching <a class="header-anchor" href="#state-initialization-and-batching" aria-label="Permalink to “State, initialization, and batching”">​</a></h2><ul><li><p>How does useState work internally?</p></li><li><p>What is the difference between direct initialization and lazy initialization?</p></li><li><p>When does a lazy initializer execute?</p></li><li><p>What happens if you call a state setter several times inside one event handler?</p></li><li><p>Does React render after every setter call?</p></li><li><p>What is batching?</p></li><li><p>How do you update state repeatedly when each update depends on the previous result?</p></li><li><p>Can you force synchronous updates instead of relying on batching?</p><p><em>flushSync is introduced as a hint. Functional updater functions are also discussed; they are a separate mechanism.</em></p></li><li><p>How does useReducer work, and how does it differ from useState?</p></li><li><p>Why should state be treated as immutable?</p></li><li><p>How would you manage updates to deeply nested state?</p></li></ul><h2 id="rendering-lifecycle-and-error-boundaries" tabindex="-1">Rendering lifecycle and error boundaries <a class="header-anchor" href="#rendering-lifecycle-and-error-boundaries" aria-label="Permalink to “Rendering lifecycle and error boundaries”">​</a></h2><ul><li><p>Explain the lifecycle of a function component, focusing on render, pre-commit, and commit.</p></li><li><p>Can hooks reproduce all the lifecycle functionality available in class components?</p></li><li><p>What functionality cannot be implemented directly with existing function-component hooks?</p><p><em>Error boundaries are the example discussed.</em></p></li><li><p>What happens if a component throws an unhandled error during rendering?</p></li></ul><h2 id="effects" tabindex="-1">Effects <a class="header-anchor" href="#effects" aria-label="Permalink to “Effects”">​</a></h2><ul><li><p>Coding/discussion task: Add a useEffect containing a fetch operation and explain when it executes.</p></li><li><p>How does the dependency array control effect execution?</p></li><li><p>What happens if you remove the dependency array?</p></li><li><p>Have you used useLayoutEffect, and how does it differ from useEffect?</p></li></ul><h2 id="hook-categories-and-custom-hooks" tabindex="-1">Hook categories and custom hooks <a class="header-anchor" href="#hook-categories-and-custom-hooks" aria-label="Permalink to “Hook categories and custom hooks”">​</a></h2><ul><li><p>How would you group React hooks by purpose? Give examples beyond useState and useReducer.</p></li><li><p>Do you use custom hooks? How do you design and create them?</p></li><li><p>What rules apply when extracting reusable logic into a custom hook?</p></li><li><p>Why can’t you call ordinary hooks conditionally?</p></li><li><p>How does hook call order allow React to associate state with the correct hook?</p></li></ul><h2 id="reusing-logic-and-component-composition" tabindex="-1">Reusing logic and component composition <a class="header-anchor" href="#reusing-logic-and-component-composition" aria-label="Permalink to “Reusing logic and component composition”">​</a></h2><ul><li><p>Besides custom hooks, what patterns can you use to reuse logic in React?</p></li><li><p>Coding task: Write a simple higher-order component.</p></li><li><p>Does your HOC return a component function, or an already-created element?</p><p><em>This is a corrective follow-up to the implementation.</em></p></li><li><p>What other reuse patterns do you know?</p><p><em>Render props and composition through children are explained and demonstrated.</em></p></li></ul><h2 id="react-dom-apis" tabindex="-1">React DOM APIs <a class="header-anchor" href="#react-dom-apis" aria-label="Permalink to “React DOM APIs”">​</a></h2><ul><li>What do these APIs do, and when would you use each? <ul><li>createRoot</li><li>hydrateRoot</li><li>createPortal</li></ul></li></ul><h2 id="keys-reconciliation-and-performance" tabindex="-1">Keys, reconciliation, and performance <a class="header-anchor" href="#keys-reconciliation-and-performance" aria-label="Permalink to “Keys, reconciliation, and performance”">​</a></h2><ul><li><p>What is the purpose of key, and how does it affect React’s handling of a list?</p></li><li><p>What happens if you omit a key?</p></li><li><p>What happens if two sibling elements have the same key?</p></li><li><p>How does React compare successive element trees?</p></li><li><p>Which hooks and APIs can you use to improve component performance?</p></li><li><p>What performance-related improvements have you heard about in React 19?</p></li><li><p>Is the claim that you no longer need manual memoization accurate?</p><p><em>This is an exploratory discussion, not a deeply assessed topic.</em></p></li><li><p>How do you measure React performance in practice?</p></li><li><p>How do you decide whether a component needs optimization?</p></li><li><p>Is memoization the only way to prevent an expensive component from rendering unnecessarily?</p></li><li><p>Composition exercise: If an expensive component is passed through children from a parent, instead of being instantiated inside a component with changing local state, can that help avoid unnecessary renders? Why?</p></li></ul><h2 id="redux-fundamentals" tabindex="-1">Redux fundamentals <a class="header-anchor" href="#redux-fundamentals" aria-label="Permalink to “Redux fundamentals”">​</a></h2><ul><li><p>What are Redux’s three main principles?</p></li><li><p>What are its main building blocks?</p><p><em>The interviewer moves between “principles” and “building blocks”; the latter discussion concerns store, actions, and reducers.</em></p></li><li><p>Where does Redux state live?</p></li><li><p>How do you update data in the store from a component?</p></li><li><p>Coding task: Write a simple reducer.</p></li><li><p>What must a reducer return after updating state?</p></li><li><p>How do you read Redux state inside a component?</p></li><li><p>What does a selector function look like?</p></li><li><p>When would you choose Redux over Context, or Context over Redux?</p></li></ul><h2 id="redux-normalization-and-asynchronous-operations" tabindex="-1">Redux normalization and asynchronous operations <a class="header-anchor" href="#redux-normalization-and-asynchronous-operations" aria-label="Permalink to “Redux normalization and asynchronous operations”">​</a></h2><ul><li><p>What is state normalization in Redux?</p></li><li><p>What does a poorly structured state shape look like, and how would you improve it?</p></li><li><p>Data-shape exercise: How difficult is it to read the supplied nested orders/items data? How could you normalize it?</p></li><li><p>How do you handle asynchronous operations in a Redux application?</p><p><em>Redux Thunk, Redux Saga, and loading/success/failure actions are discussed.</em></p></li></ul><h2 id="react-router" tabindex="-1">React Router <a class="header-anchor" href="#react-router" aria-label="Permalink to “React Router”">​</a></h2><ul><li><p>Have you used React Router?</p></li><li><p>How does it enable navigation without a full-page reload?</p></li><li><p>Which router types are commonly used?</p></li><li><p>Which browser API does routing use to navigate?</p><p><em>The discussion includes browser, hash, memory, and static routers, plus the History API.</em></p></li></ul><h2 id="react-testing" tabindex="-1">React testing <a class="header-anchor" href="#react-testing" aria-label="Permalink to “React testing”">​</a></h2><ul><li><p>What experience do you have writing unit tests for React applications?</p></li><li><p>What is the difference between shallow rendering and full rendering?</p></li><li><p>When would you use one approach over the other?</p></li><li><p>How do you test components that make API calls?</p></li><li><p>Have you used Mock Service Worker (MSW)? How does it work?</p></li><li><p>Which React Testing Library queries do you know?</p></li><li><p>What is the Arrange–Act–Assert pattern?</p></li><li><p>How do you simulate user events in a component test? Which two approaches/APIs do you know?</p><p><em>The transcript does not clearly capture both intended API names; fireEvent is discussed.</em></p></li><li><p>After rendering a component containing a button, how would you find that button?</p><p><em>The interviewer introduces screen and role-based queries.</em></p></li></ul><h2 id="rendering-strategies-and-next-js" tabindex="-1">Rendering strategies and Next.js <a class="header-anchor" href="#rendering-strategies-and-next-js" aria-label="Permalink to “Rendering strategies and Next.js”">​</a></h2><ul><li><p>Which rendering strategies do you know and use?</p></li><li><p>What benefits does server-side rendering provide?</p></li><li><p>Explain the SSR request lifecycle:</p><ul><li>What does the client request?</li><li>What does the server do?</li><li>What does it return?</li><li>What does the browser do next?</li></ul></li><li><p>Do you use Next.js App Router, Pages Router, or both?</p></li><li><p>How do you implement static generation and incremental regeneration/revalidation with App Router?</p></li><li><p>How does that differ from the Pages Router approach?</p></li></ul><h2 id="build-tools-and-production-optimization" tabindex="-1">Build tools and production optimization <a class="header-anchor" href="#build-tools-and-production-optimization" aria-label="Permalink to “Build tools and production optimization”">​</a></h2><ul><li><p>What is the difference between a transpiler and a compiler?</p></li><li><p>What role does Babel play when building a React application?</p></li><li><p>What differs between development and production builds?</p></li><li><p>How does React’s performance differ between those builds?</p></li><li><p>How can you optimize a production bundle?</p></li><li><p>What is tree shaking?</p></li><li><p>Example discussion: If a module exports two functions but the application uses only one, what can happen to the unused function during bundling?</p></li></ul><p>Explicitly skipped or not fully explored: forms, Context as a standalone topic, and type checking. They should not be counted as assessed questions.</p>',33)])])}const m=i(n,[["render",l]]);export{h as __pageData,m as default};
